import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def solve(i):
    H=len(i); W=len(i[0])
    blocks=[(r,c) for r in range(H-1) for c in range(W-1) if i[r][c]==2 and i[r][c+1]==2 and i[r+1][c]==2 and i[r+1][c+1]==2]
    out=[[0]*W for _ in range(H)]
    for br,bc in blocks:
        for r in range(br,br+2):
            for c in range(bc,bc+2):
                out[r][c]=2
    seeds=[(r,c) for r in range(H) for c in range(W) if i[r][c] not in (0,2)]
    for r,c in sorted(seeds,key=lambda s:s[0]+s[1]):
        v=i[r][c]
        cr,cc=min(blocks,key=lambda b:abs(b[0]-r)+abs(b[1]-c))
        ctr,ctc=cr+0.5,cc+0.5
        dr=r-ctr; dc=c-ctc
        nr=int(round(ctr+dc)); nc=int(round(ctc-dr))
        sr=-1 if nr<=ctr else 1
        sc=-1 if nc<=ctc else 1
        rr,rc=nr,nc
        while 0<=rr<H and 0<=rc<W and out[rr][rc]!=2:
            out[rr][rc]=v; rr+=sr; rc+=sc
    return out
