def solve_var(i,nf,rot,sab):
    H=len(i); W=len(i[0])
    blocks=[(r,c) for r in range(H-1) for c in range(W-1) if i[r][c]==2 and i[r][c+1]==2 and i[r+1][c]==2 and i[r+1][c+1]==2]
    out=[[0]*W for _ in range(H)]
    for br,bc in blocks:
        for r in range(br,br+2):
            for c in range(bc,bc+2):
                out[r][c]=2
    seeds=[(r,c) for r in range(H) for c in range(W) if i[r][c] not in (0,2)]
    for r,c in seeds:
        v=i[r][c]
        b=min(blocks,key=lambda bb:nf((r,c),(bb[0],bb[1])))
        cr,cc=b; ctr,ctc=cr+0.5,cc+0.5
        dr=r-ctr; dc=c-ctc
        if rot=='cw': nr,nc=ctr+dc,ctc-dr
        elif rot=='ccw': nr,nc=ctr-dc,ctc+dr
        else: nr,nc=ctr-dr,ctc-dc
        sr=-1 if nr<=ctr else 1
        sc=-1 if nc<=ctc else 1
        rr,rc=int(nr),int(nc)
        while 0<=rr<H and 0<=rc<W:
            if sab and out[rr][rc]==2: break
            if out[rr][rc]!=0: break
            out[rr][rc]=v
            rr+=sr; rc+=sc
    return out
