        rr,rc=n
        while 0<=rr<H and 0<=rc<W and out[rr][rc]!=2:
            if out[rr][rc]==0:
                out[rr][rc]=v
            if (rr,rc)==(r,c): break
            rr+=sr; rc+=sc
        out[r][c]=0
